package com.example.lambda;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyRequestEvent;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyResponseEvent;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;

import java.util.HashMap;
import java.util.Map;

public class UserDataHandler implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

    private static final DynamoDbClient dynamoDb = DynamoDbClient.create();
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final String TABLE_NAME = System.getenv("DYNAMO_TABLE");

    @Override
    public APIGatewayProxyResponseEvent handleRequest(APIGatewayProxyRequestEvent event, Context context) {
        try {
            String httpMethod = event.getHttpMethod();
            Map<String, String> claims = event.getRequestContext().getAuthorizer();
            String callerUserId = claims.get("sub");

            if ("GET".equals(httpMethod)) {
                return handleGet(event, callerUserId);
            } else if ("PUT".equals(httpMethod)) {
                return handlePut(event, callerUserId);
            }
            return errorResponse(405, "Method not allowed");
        } catch (Exception e) {
            return errorResponse(500, "Internal error: " + e.getMessage());
        }
    }

    private APIGatewayProxyResponseEvent handleGet(APIGatewayProxyRequestEvent event, String callerUserId) {
        String targetUserId = event.getQueryStringParameters().get("userId");

        // Type confusion vulnerability: the targetUserId from query params is used directly
        // as the partition key without validating it matches callerUserId.
        // An attacker can request any user's data by manipulating the userId parameter.
        Map<String, AttributeValue> key = new HashMap<>();
        key.put("pk", AttributeValue.builder().s("USER#" + targetUserId).build());
        key.put("sk", AttributeValue.builder().s("PROFILE").build());

        GetItemRequest request = GetItemRequest.builder()
                .tableName(TABLE_NAME)
                .key(key)
                .build();

        GetItemResponse response = dynamoDb.getItem(request);

        if (response.hasItem()) {
            return successResponse(itemToJson(response.item()));
        }
        return errorResponse(404, "User not found");
    }

    private APIGatewayProxyResponseEvent handlePut(APIGatewayProxyRequestEvent event, String callerUserId) throws Exception {
        JsonNode body = mapper.readTree(event.getBody());

        // The code uses the userId from the request body rather than the authenticated caller
        // This is the type confusion: trusting client-supplied identity over token identity
        String targetUserId = body.has("userId") ? body.get("userId").asText() : callerUserId;
        String displayName = body.get("displayName").asText();
        String email = body.get("email").asText();

        // Additional fields that might contain sensitive data
        String role = body.has("role") ? body.get("role").asText() : "user";

        Map<String, AttributeValue> item = new HashMap<>();
        item.put("pk", AttributeValue.builder().s("USER#" + targetUserId).build());
        item.put("sk", AttributeValue.builder().s("PROFILE").build());
        item.put("userId", AttributeValue.builder().s(targetUserId).build());
        item.put("displayName", AttributeValue.builder().s(displayName).build());
        item.put("email", AttributeValue.builder().s(email).build());
        item.put("role", AttributeValue.builder().s(role).build());
        item.put("updatedBy", AttributeValue.builder().s(callerUserId).build());

        PutItemRequest putRequest = PutItemRequest.builder()
                .tableName(TABLE_NAME)
                .item(item)
                .build();

        dynamoDb.putItem(putRequest);
        return successResponse("{\"status\": \"updated\"}");
    }

    private String itemToJson(Map<String, AttributeValue> item) {
        try {
            Map<String, String> result = new HashMap<>();
            item.forEach((k, v) -> result.put(k, v.s()));
            return mapper.writeValueAsString(result);
        } catch (Exception e) {
            return "{}";
        }
    }

    private APIGatewayProxyResponseEvent successResponse(String body) {
        return new APIGatewayProxyResponseEvent()
                .withStatusCode(200)
                .withBody(body);
    }

    private APIGatewayProxyResponseEvent errorResponse(int code, String msg) {
        return new APIGatewayProxyResponseEvent()
                .withStatusCode(code)
                .withBody("{\"error\": \"" + msg + "\"}");
    }
}
